INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001540171','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001540171","revision":1,"targetId":"80000000-0000-4000-8000-000000015417","prompt":"Der Staat erhebt auf viele Waren einen Betrag, der im Verkaufspreis enthalten ist. Wie nennt man diese Abgabe?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"It is a compulsory levy, not a voluntary payment.","de":"Es ist eine gesetzliche Abgabe und keine freiwillige Zahlung."},"options":[{"id":"0","text":"ein Pfand"},{"id":"1","text":"eine Steuer"},{"id":"2","text":"ein Trinkgeld"},{"id":"3","text":"einen Rabatt"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Value-added tax is one kind of Steuer.","de":"Die Umsatzsteuer ist eine Art von Steuer."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Betrag ist eine Steuer, zum Beispiel die Umsatzsteuer.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2256 (828cd1052072cb751080b8b0d4c4bcac1faee9da57c901278d5d6e4d35403169), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
