INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001540181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001540181","revision":1,"targetId":"80000000-0000-4000-8000-000000015418","prompt":"Eine Selbstständige sucht fachliche Hilfe bei der Erstellung ihres Jahresabschlusses und ihrer Steuererklärung. Wohin wendet sie sich?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"She needs an adviser, not a government tax authority.","de":"Sie sucht Beratung und keine Behörde zur Steuerfestsetzung."},"options":[{"id":"0","text":"an ein Steuerbüro"},{"id":"1","text":"an das Fundbüro"},{"id":"2","text":"an die Fahrschule"},{"id":"3","text":"an die Stadtbibliothek"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"A Steuerbüro can advise on accounts and tax returns.","de":"Ein Steuerbüro kann bei Jahresabschluss und Steuererklärung beraten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie wendet sich an ein Steuerbüro.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2257 (e01e7043d4a3308370de6bda50b8a4455f65918ef59493b2c4bb8ece79b71aa6), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
