INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001540190','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001540190","revision":1,"targetId":"80000000-0000-4000-8000-000000015419","prompt":"Sie sammelt Belege, bevor sie ihre ___ beim Finanzamt einreicht.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"The document reports tax-relevant income and expenses.","de":"Das Dokument enthält Angaben zu steuerlich wichtigen Einnahmen und Ausgaben."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Fahrkarte"},{"id":"1","text":"Bewerbung"},{"id":"2","text":"Steuererklärung"},{"id":"3","text":"Mietzahlung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"A Steuererklärung is a declaration submitted for taxation.","de":"Eine Steuererklärung enthält Angaben für die steuerliche Veranlagung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie sammelt Belege, bevor sie ihre Steuererklärung beim Finanzamt einreicht.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2258 (c0afd91e61ed2b718274e60ff74dff9e2ac3f2967374b8f72ff3cf74f491bc86), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
