INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001540191','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001540191","revision":1,"targetId":"80000000-0000-4000-8000-000000015419","prompt":"Ein Selbstständiger muss dem Finanzamt seine Einkünfte und abziehbaren Ausgaben für das Jahr mitteilen. Welches Dokument erstellt er?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The document declares financial information for tax assessment.","de":"Das Dokument dient der steuerlichen Erklärung der Einkünfte."},"options":[{"id":"0","text":"eine Stellenanzeige"},{"id":"1","text":"einen Arbeitsvertrag"},{"id":"2","text":"einen Lieferschein"},{"id":"3","text":"eine Steuererklärung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"A tax return reports income and relevant deductions.","de":"Eine Steuererklärung nennt Einkünfte und steuerlich relevante Abzüge."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Er erstellt eine Steuererklärung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2258 (c0afd91e61ed2b718274e60ff74dff9e2ac3f2967374b8f72ff3cf74f491bc86), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
