INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001550000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001550000","revision":1,"targetId":"80000000-0000-4000-8000-000000015500","prompt":"Für die Berechnung der Lohnsteuer wird auf der Gehaltsabrechnung die ___ angegeben.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"The information affects payroll tax withholding.","de":"Die Angabe spielt beim Lohnsteuerabzug eine Rolle."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Urlaubsplanung"},{"id":"1","text":"Dienstkleidung"},{"id":"2","text":"Steuerklasse"},{"id":"3","text":"Arbeitsanweisung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Steuerklasse identifies a category relevant to wage-tax deductions.","de":"Die Steuerklasse ist eine für den Lohnsteuerabzug relevante Kategorie."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Berechnung der Lohnsteuer wird auf der Gehaltsabrechnung die Steuerklasse angegeben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2259 (980f10d9801f4b279afe7c3dfc1b7ec5e285635270c402e499c67955aeb9eb30), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
